<?php
$practiceModel = new \App\Models\PracticeAreaModel();
$activeAreas = $practiceModel->where('is_active',1)->orderBy('sort_order','ASC')->findAll();
$renderSection = static function(array $s) use ($practice, $activeAreas): string {
    if (!empty($s['hidden'])) return '';
    $d=$s['data']??[]; $type=$s['type']??'richtext'; $theme=($d['theme']??'light')==='dark'?'dark':'light';
    $esc=static fn($v)=>esc((string)$v); $html='';
    switch($type){
        case 'hero':
            $image=$d['image']??$practice['image']; $html='<section class="page-hero practice-page-hero '.($theme==='dark'?'dark':'').'">'.'<div class="container page-hero-grid"><div class="reveal"><div class="eyebrow">'.$esc($d['eyebrow']??'Practice Area').'</div><h1>'.$esc($d['title']??$practice['name']).'</h1><p>'.$esc($d['text']??$practice['short_description']).'</p>'.(!empty($d['button_text'])?'<a class="btn btn-gold" href="'.site_url($d['button_url']??'appointment').'">'.$esc($d['button_text']).'</a>':'').'</div><div class="page-art glass-card reveal">'.($image?'<img class="practice-page-image" src="'.esc(base_url($image)).'" alt="'.$esc($practice['name']).' legal illustration">':'').'</div></div><div class="orb main" data-depth=".55"></div><div class="orbit" data-depth=".85"></div></section>'; break;
        case 'html':
            $html='<section class="section '.$theme.'"><div class="container dynamic-builder-html">'.($d['content']??'').'</div></section>'; break;
        case 'richtext':
            $html='<section class="section '.$theme.'"><div class="container dynamic-builder-rich"><div class="eyebrow">'.$esc($d['eyebrow']??'').'</div>'.(!empty($d['title'])?'<h2>'.$esc($d['title']).'</h2>':'').'<div class="builder-rich-content">'.($d['content']??'').'</div></div></section>'; break;
        case 'process':
        case 'cards':
            $items=is_array($d['items']??null)?$d['items']:[]; $html='<section class="section '.$theme.'"><div class="container"><div class="section-head reveal"><div><div class="eyebrow">'.$esc($d['eyebrow']??'').'</div><h2>'.$esc($d['title']??'').'</h2></div></div><div class="detail-grid">'; foreach($items as $it){$html.='<div class="detail-block reveal"><span class="eyebrow">'.$esc($it['label']??'').'</span><h3>'.$esc($it['title']??'').'</h3><div>'.($it['text']??'').'</div></div>';} $html.='</div></div></section>'; break;
        case 'quote':
            $html='<section class="section '.$theme.'"><div class="container matter-quote glass-light builder-quote"><span class="smallcaps">'.$esc($d['label']??'LEX FACTUM').'</span><blockquote>'.$esc($d['quote']??'').'</blockquote><div>'.($d['text']??'').'</div></div></section>'; break;
        case 'image_text':
            $img=$d['image']??''; $side=($d['side']??'right')==='left'?'image-left':'image-right'; $html='<section class="section '.$theme.'"><div class="container feature-practice '.$side.'"><div class="feature-copy reveal"><div class="eyebrow">'.$esc($d['eyebrow']??'').'</div><h2>'.$esc($d['title']??'').'</h2><div>'.$d['content']??''. '</div></div><div class="feature-art glass-card reveal">'.($img?'<img class="practice-feature-image" src="'.esc(base_url($img)).'" alt="'.$esc($practice['name']).'">':'').'</div></div></section>'; break;
        case 'cta':
            $html='<section class="section '.$theme.'"><div class="container cta-builder"><div><div class="eyebrow">'.$esc($d['eyebrow']??'').'</div><h2>'.$esc($d['title']??'').'</h2><div>'.($d['content']??'').'</div></div>'.(!empty($d['button_text'])?'<a class="btn btn-gold" href="'.site_url($d['button_url']??'appointment').'">'.$esc($d['button_text']).'</a>':'').'</div></section>'; break;
        case 'related':
            $limit=max(1,min(12,(int)($d['limit']??4))); $items=array_values(array_filter($activeAreas,fn($a)=>(int)$a['id']!==(int)$practice['id'])); $items=array_slice($items,0,$limit); $html='<section class="section '.$theme.'"><div class="container section-head reveal"><div><div class="eyebrow">Continue exploring</div><h2>'.$esc($d['title']??'Other practice areas.').'</h2></div><a class="btn btn-glass" href="'.site_url('practice-areas').'">View all areas ↗</a></div><div class="container related-grid">'; foreach($items as $a){$html.='<a class="related-item glass-highlight" href="'.site_url($a['slug']).'"><span>↗</span><strong>'.$esc($a['name']).'</strong><em>Explore</em></a>';} $html.='</div></section>'; break;
    }
    return $html;
};
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($practice['name']) ?> — Lex Factum & Partners</title><meta name="description" content="<?= esc($practice['short_description']) ?>"><link rel="stylesheet" href="<?= base_url('styles.css') ?>"><style>.dynamic-builder-html{line-height:1.75}.dynamic-builder-html .matter-rich{margin:0}.dynamic-builder-html .feature-practice{margin:0}.dynamic-builder-html h2{margin-bottom:18px}.dynamic-builder-rich h2{margin-bottom:18px}.builder-rich-content{line-height:1.85}.builder-rich-content p{margin:0 0 16px}.builder-rich-content h3{margin:25px 0 10px}.builder-rich-content ul,.builder-rich-content ol{padding-left:22px}.builder-quote{max-width:900px;margin:0 auto}.builder-quote blockquote{margin:18px 0;font:500 clamp(30px,4vw,52px)/1.08 Georgia,serif}.image-left .feature-copy{order:2}.image-left .feature-art{order:1}.cta-builder{display:flex;align-items:center;justify-content:space-between;gap:30px}.cta-builder>div:first-child{max-width:760px}.dark .builder-rich-content,.dark .builder-rich-content p,.dark .detail-block div,.dark .cta-builder p{color:#c6c9c8}.dark .dynamic-builder-html{line-height:1.75}.dynamic-builder-html .matter-rich{margin:0}.dynamic-builder-html .feature-practice{margin:0}.dynamic-builder-html h2{margin-bottom:18px}.dynamic-builder-rich h2,.dark .builder-rich-content h3{color:#f0efeb}@media(max-width:800px){.cta-builder{display:block}.cta-builder .btn{margin-top:20px}}</style></head><body><div class="grain"></div><div class="cursor-ring"></div><div class="cursor-dot"></div><div class="progress"></div><header><div class="container nav-shell"><a class="brand" href="<?= site_url('/') ?>"><span class="brand-mark"><img src="<?= base_url('assets/lex-factum-logo-transparent.png') ?>" alt="Lex Factum & Partners"></span><span class="brand-copy"><strong>Lex Factum</strong><span>& PARTNERS · LAW FIRM</span></span></a><nav class="menu"><a href="<?= site_url('/') ?>">Home</a><a href="<?= site_url('about') ?>">About</a><a href="<?= site_url('practice-areas') ?>">Practice</a><a href="<?= site_url('updates') ?>">Updates</a><a href="<?= site_url('faq') ?>">FAQ</a><a href="<?= site_url('contact') ?>">Contact</a><a class="nav-cta" href="<?= site_url('appointment') ?>">Request Appointment ↗</a></nav><button class="burger" aria-label="menu">☰</button></div></header><main><?php foreach($sections as $section) echo $renderSection($section); ?></main><footer><div class="container footer-grid"><div class="footer-brand"><a class="brand" href="<?= site_url('/') ?>"><span class="brand-mark"><img src="<?= base_url('assets/lex-factum-logo-transparent.png') ?>" alt="Lex Factum & Partners"></span><span class="brand-copy"><strong>Lex Factum</strong><span>& PARTNERS · LAW FIRM</span></span></a><p>Lex Factum & Partners – law firm having its head-office in New Delhi. We strive to provide par-excellence legal services across India.</p></div><div><div class="footer-title">Explore</div><div class="footer-links"><a href="<?= site_url('about') ?>">About</a><a href="<?= site_url('practice-areas') ?>">Practice Areas</a><a href="<?= site_url('updates') ?>">Updates</a><a href="<?= site_url('faq') ?>">FAQ</a><a href="<?= site_url('contact') ?>">Contact</a></div></div><div><div class="footer-title">Practice</div><div class="footer-links"><a href="<?= site_url('practice-areas') ?>">All Practice Areas</a><?php foreach(array_slice($activeAreas,0,4) as $a): ?><a href="<?= site_url($a['slug']) ?>"><?= esc($a['name']) ?></a><?php endforeach; ?></div></div><div><div class="footer-title">Contact</div><div class="footer-links"><a href="<?= site_url('appointment') ?>">Request Appointment</a><span>New Delhi · India</span><span>+91 9152946757</span></div></div><div class="footer-bottom">Copyright © 2026 Lex Factum & Partners</div></div></footer><script src="<?= base_url('script.js') ?>"></script></body></html>
